import React, { useState, useRef, useEffect } from 'react';
import { HostDetail, HostStay } from '../types';
import { formatDate } from '../utils/dateUtils';
import { uploadBankbook, uploadBusinessRegistration, deleteBusinessRegistration } from '../utils/hostApi';
import { useToast } from '../hooks/useToast';
import BankbookUploadForm from './BankbookUploadForm';
import BusinessRegistrationUploadForm from './BusinessRegistrationUploadForm';
import StayList from './StayList';
import BankbookImageModal from './BankbookImageModal';

interface HostDetailModalProps {
  isOpen: boolean;
  host: HostDetail;
  stays: HostStay[];
  onClose: () => void;
  onUpdate: () => void;
  onPasswordReset: () => void;
  isPasswordModalOpen?: boolean;
}

const HostDetailModal: React.FC<HostDetailModalProps> = ({
  isOpen,
  host,
  stays,
  onClose,
  onUpdate,
  onPasswordReset,
  isPasswordModalOpen = false,
}) => {
  const [showStays, setShowStays] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [isDeletingBusinessRegistration, setIsDeletingBusinessRegistration] = useState(false);
  const [bankbookImageModalOpen, setBankbookImageModalOpen] = useState(false);
  const [businessRegistrationImageModalOpen, setBusinessRegistrationImageModalOpen] = useState(false);
  const modalRef = useRef<HTMLDivElement>(null);
  const { showToast } = useToast();

  // 모달이 열릴 때마다 Stay 정보 토글 초기화
  useEffect(() => {
    if (isOpen) {
      setShowStays(false);
    }
  }, [isOpen]);

  // 외부 클릭 감지
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (modalRef.current && !modalRef.current.contains(event.target as Node)) {
        // 비밀번호 초기화 모달이 열려있으면 외부 클릭 무시
        if (!isUploading && !isDeletingBusinessRegistration && !isPasswordModalOpen) {
          onClose();
        }
      }
    };

    if (isOpen) {
      document.addEventListener('mousedown', handleClickOutside);
    }

    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [isOpen, onClose, isUploading, isDeletingBusinessRegistration, isPasswordModalOpen]);

  // ESC 키 감지
  useEffect(() => {
    const handleEscapeKey = (event: KeyboardEvent) => {
      if (event.key === 'Escape' && !isUploading && !bankbookImageModalOpen && !businessRegistrationImageModalOpen && !isPasswordModalOpen) {
        onClose();
      }
    };

    if (isOpen) {
      document.addEventListener('keydown', handleEscapeKey);
    }

    return () => {
      document.removeEventListener('keydown', handleEscapeKey);
    };
  }, [isOpen, onClose, isUploading, bankbookImageModalOpen, businessRegistrationImageModalOpen, isPasswordModalOpen]);

  const handleBankbookUpload = async (file: File, specialNote?: string) => {
    setIsUploading(true);
    try {
      await uploadBankbook(host.id, file, specialNote);
      showToast('통장사본이 성공적으로 업로드되었습니다.', 'success');
      onUpdate();
    } catch (error) {
      showToast(
        error instanceof Error ? error.message : '통장사본 업로드에 실패했습니다.',
        'error'
      );
    } finally {
      setIsUploading(false);
    }
  };

  const handleBankbookImageClick = () => {
    if (host.bankbookUrl) {
      setBankbookImageModalOpen(true);
    }
  };

  const handleBusinessRegistrationUpload = async (file: File, specialNote?: string) => {
    setIsUploading(true);
    try {
      await uploadBusinessRegistration(host.id, file, specialNote);
      showToast('사업자등록증이 성공적으로 업로드되었습니다.', 'success');
      onUpdate();
    } catch (error) {
      showToast(
        error instanceof Error ? error.message : '사업자등록증 업로드에 실패했습니다.',
        'error'
      );
    } finally {
      setIsUploading(false);
    }
  };

  const handleBusinessRegistrationDelete = async () => {
    setIsDeletingBusinessRegistration(true);
    try {
      await deleteBusinessRegistration(host.id);
      showToast('사업자등록증이 성공적으로 삭제되었습니다.', 'success');
      onUpdate();
    } catch (error) {
      showToast(
        error instanceof Error ? error.message : '사업자등록증 삭제에 실패했습니다.',
        'error'
      );
    } finally {
      setIsDeletingBusinessRegistration(false);
    }
  };

  const handleBusinessRegistrationImageClick = () => {
    if (host.businessRegistrationUrl) {
      setBusinessRegistrationImageModalOpen(true);
    }
  };

  if (!isOpen) {
    return null;
  }

  return (
    <>
      {/* 배경 딤 */}
      <div className="fixed inset-0 bg-black bg-opacity-50 z-50 flex items-center justify-center p-4">
        {/* 모달 */}
        <div
          ref={modalRef}
          className="bg-white rounded-lg shadow-xl w-full max-w-2xl max-h-[90vh] overflow-y-auto animate-fade-in"
        >
          {/* 헤더 */}
          <div className="flex items-center justify-between p-4 border-b border-gray-200 sticky top-0 bg-white z-10">
            <h3 className="text-lg font-medium text-gray-900">Host 상세 정보</h3>
            <button
              onClick={onClose}
              disabled={isUploading || isDeletingBusinessRegistration}
              className="text-gray-400 hover:text-gray-600 transition-colors disabled:opacity-50"
              aria-label="모달 닫기"
            >
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
              </svg>
            </button>
          </div>

          {/* 내용 */}
          <div className="p-6 space-y-6">
            {/* Host 정보 섹션 */}
            <div>
              <h4 className="text-md font-semibold text-gray-900 mb-4">Host 정보</h4>
              <div className="space-y-3">
                <div>
                  <label className="block text-sm font-medium text-gray-700">ID</label>
                  <p className="mt-1 text-sm text-gray-900">{host.id}</p>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700">이름</label>
                  <p className="mt-1 text-sm text-gray-900">{host.hostName}</p>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700">연락처</label>
                  <p className="mt-1 text-sm text-gray-900">{host.contact}</p>
                </div>
                {host.specialNote && (
                  <div>
                    <label className="block text-sm font-medium text-gray-700">특이사항</label>
                    <p className="mt-1 text-sm text-gray-900 whitespace-pre-wrap">{host.specialNote}</p>
                  </div>
                )}
                <div>
                  <label className="block text-sm font-medium text-gray-700">생성일</label>
                  <p className="mt-1 text-sm text-gray-900">{formatDate(host.createdDate)}</p>
                </div>
                {host.updatedDate !== host.createdDate && (
                  <div>
                    <label className="block text-sm font-medium text-gray-700">수정일</label>
                    <p className="mt-1 text-sm text-gray-900">{formatDate(host.updatedDate)}</p>
                  </div>
                )}
              </div>
            </div>

            {/* 통장사본 관리 섹션 */}
            <div>
              <h4 className="text-md font-semibold text-gray-900 mb-4">통장사본 관리</h4>
              <BankbookUploadForm
                currentBankbookUrl={host.bankbookUrl}
                onUpload={handleBankbookUpload}
                isUploading={isUploading}
                onImageClick={handleBankbookImageClick}
              />
            </div>

            {/* 사업자등록증 관리 섹션 */}
            <div>
              <h4 className="text-md font-semibold text-gray-900 mb-4">사업자등록증 관리</h4>
              <BusinessRegistrationUploadForm
                currentBusinessRegistrationUrl={host.businessRegistrationUrl}
                onUpload={handleBusinessRegistrationUpload}
                onDelete={handleBusinessRegistrationDelete}
                isUploading={isUploading}
                isDeleting={isDeletingBusinessRegistration}
                onImageClick={handleBusinessRegistrationImageClick}
              />
            </div>

            {/* Stay 정보 섹션 */}
            <div>
              <div className="flex items-center justify-between mb-4">
                <h4 className="text-md font-semibold text-gray-900">Stay 정보</h4>
                <button
                  onClick={() => setShowStays(!showStays)}
                  className="px-3 py-1 text-sm bg-gray-100 text-gray-700 rounded-lg hover:bg-gray-200 transition-colors"
                >
                  {showStays ? '숨기기' : '보기'}
                </button>
              </div>
              {showStays ? (
                <StayList stays={stays} onUpdate={onUpdate} />
              ) : (
                <p className="text-sm text-gray-500">Stay 정보 숨김</p>
              )}
            </div>

            {/* 비밀번호 초기화 섹션 */}
            <div>
              <h4 className="text-md font-semibold text-gray-900 mb-4">비밀번호 관리</h4>
              <button
                onClick={onPasswordReset}
                disabled={isUploading}
                className="px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
              >
                비밀번호 초기화
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* 통장사본 이미지 확대 모달 */}
      {host.bankbookUrl && (
        <BankbookImageModal
          isOpen={bankbookImageModalOpen}
          imageUrl={host.bankbookUrl}
          onClose={() => setBankbookImageModalOpen(false)}
        />
      )}

      {/* 사업자등록증 이미지 확대 모달 */}
      {host.businessRegistrationUrl && (
        <BankbookImageModal
          isOpen={businessRegistrationImageModalOpen}
          imageUrl={host.businessRegistrationUrl}
          onClose={() => setBusinessRegistrationImageModalOpen(false)}
        />
      )}
    </>
  );
};

export default HostDetailModal;

