import React from 'react';
import { Toast, ToastType } from '../../hooks/useToast';

interface ToastNotificationProps {
  toast: Toast;
  onClose: (id: string) => void;
}

const ToastNotification: React.FC<ToastNotificationProps> = ({ toast, onClose }) => {
  const getToastStyles = (type: ToastType): string => {
    const baseStyles = 'fixed bottom-5 left-1/2 transform -translate-x-1/2 px-4 py-3 rounded-lg shadow-lg text-white font-medium z-50 transition-all duration-300 ease-in-out';
    
    switch (type) {
      case 'success':
        return `${baseStyles} bg-green-500`;
      case 'error':
        return `${baseStyles} bg-red-500`;
      case 'info':
      default:
        return `${baseStyles} bg-blue-500`;
    }
  };

  const getIcon = (type: ToastType): string => {
    switch (type) {
      case 'success':
        return '✓';
      case 'error':
        return '✕';
      case 'info':
      default:
        return 'ℹ';
    }
  };

  return (
    <div className={getToastStyles(toast.type)}>
      <div className="flex items-center gap-2">
        <span className="text-lg">{getIcon(toast.type)}</span>
        <span>{toast.message}</span>
        <button
          onClick={() => onClose(toast.id)}
          className="ml-2 text-white hover:text-gray-200 transition-colors"
          aria-label="토스트 닫기"
        >
          ✕
        </button>
      </div>
    </div>
  );
};

export default ToastNotification; 