import React, { useState, useEffect, useRef } from 'react';
import { Stay } from '../types';
import { searchStaysByAddress, updateOrderAddress } from '../utils/staySearchApi';
import { useToast } from '../hooks/useToast';

interface StaySearchModalProps {
  isOpen: boolean;
  onClose: () => void;
  orderId: string;
  address: string;
}

const StaySearchModal: React.FC<StaySearchModalProps> = ({
  isOpen,
  onClose,
  orderId,
  address,
}) => {
  const [loading, setLoading] = useState(false);
  const [stays, setStays] = useState<Stay[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [updating, setUpdating] = useState(false);
  const [selectedStayId, setSelectedStayId] = useState<string | null>(null);
  const modalRef = useRef<HTMLDivElement>(null);
  const { showToast } = useToast();

  // 모달이 열릴 때마다 검색 실행
  useEffect(() => {
    if (isOpen && address) {
      handleSearch();
    }
  }, [isOpen, address]);

  // 외부 클릭 감지
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (modalRef.current && !modalRef.current.contains(event.target as Node)) {
        if (!loading && !updating) {
          onClose();
        }
      }
    };

    if (isOpen) {
      document.addEventListener('mousedown', handleClickOutside);
    }

    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [isOpen, onClose, loading, updating]);

  // ESC 키 감지
  useEffect(() => {
    const handleEscapeKey = (event: KeyboardEvent) => {
      if (event.key === 'Escape' && !loading && !updating) {
        onClose();
      }
    };

    if (isOpen) {
      document.addEventListener('keydown', handleEscapeKey);
    }

    return () => {
      document.removeEventListener('keydown', handleEscapeKey);
    };
  }, [isOpen, onClose, loading, updating]);

  // Stay 검색
  const handleSearch = async () => {
    if (!address) {
      setError('주소 정보가 없습니다.');
      return;
    }

    setLoading(true);
    setError(null);
    setStays([]);

    try {
      const response = await searchStaysByAddress({
        address: address,
        detailAddress: null,
      });

      if (response.success && response.data) {
        setStays(response.data);
        if (response.data.length === 0) {
          setError('매칭되는 Stay를 찾을 수 없습니다.');
        }
      }
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Stay 검색에 실패했습니다.';
      setError(errorMessage);
      setStays([]);
    } finally {
      setLoading(false);
    }
  };

  // Stay 선택 및 주소 변경
  const handleStaySelect = async (stay: Stay) => {
    if (updating) return;

    setUpdating(true);
    setSelectedStayId(stay.stay_id);
    setError(null);

    try {
      await updateOrderAddress(orderId, {
        stayId: stay.stay_id,
      });

      showToast('주소가 성공적으로 변경되었습니다.', 'success');
      
      // 페이지 새로고침
      setTimeout(() => {
        window.location.reload();
      }, 500);
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : '주소 변경에 실패했습니다.';
      setError(errorMessage);
      setSelectedStayId(null);
    } finally {
      setUpdating(false);
    }
  };

  if (!isOpen) {
    return null;
  }

  return (
    <>
      {/* 배경 딤 */}
      <div className="fixed inset-0 bg-black bg-opacity-50 z-50 flex items-center justify-center p-4">
        {/* 모달 */}
        <div
          ref={modalRef}
          className="bg-white rounded-lg shadow-xl w-full max-w-2xl max-h-[85vh] overflow-y-auto animate-fade-in"
        >
          {/* 헤더 */}
          <div className="flex items-center justify-between p-4 border-b border-gray-200 sticky top-0 bg-white z-10">
            <h3 className="text-lg font-medium text-gray-900">🔗 Stay 연동</h3>
            <button
              onClick={onClose}
              disabled={loading || updating}
              className="text-gray-400 hover:text-gray-600 transition-colors disabled:opacity-50"
              aria-label="모달 닫기"
            >
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
              </svg>
            </button>
          </div>

          {/* 본문 */}
          <div className="p-4">
            {/* 검색한 주소 정보 */}
            {address && (
              <div className="bg-blue-50 border border-blue-200 rounded-lg p-4 mb-4">
                <p className="text-xs font-medium text-blue-900 mb-1">검색한 주소:</p>
                <p className="text-sm text-blue-800">{address}</p>
              </div>
            )}

            {/* 검색 중 */}
            {loading && (
              <div className="flex flex-col items-center justify-center py-12">
                <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
                <p className="mt-4 text-gray-600">검색 중...</p>
              </div>
            )}

            {/* 에러 메시지 */}
            {error && !loading && (
              <div className="bg-red-50 border border-red-200 rounded-lg p-4 mb-4">
                <p className="text-red-800 text-sm">{error}</p>
              </div>
            )}

            {/* Stay 리스트 */}
            {!loading && stays.length > 0 && (
              <div className="space-y-3">
                <p className="text-sm text-gray-600 mb-4">
                  다음 Stay 중 하나를 선택하여 주소를 연동하세요:
                </p>
                {stays.map((stay) => (
                  <button
                    key={stay.id}
                    onClick={() => handleStaySelect(stay)}
                    disabled={updating}
                    className={`w-full text-left p-4 rounded-lg border-2 transition-all duration-200 ${
                      updating && selectedStayId === stay.stay_id
                        ? 'border-blue-500 bg-blue-50'
                        : updating
                        ? 'border-gray-200 bg-gray-50 opacity-50 cursor-not-allowed'
                        : 'border-gray-200 bg-white hover:border-blue-300 hover:bg-blue-50 cursor-pointer'
                    }`}
                  >
                    <div className="flex items-center justify-between">
                      <div className="flex-1">
                        <p className="font-medium text-gray-900">{stay.stay_name}</p>
                        {updating && selectedStayId === stay.stay_id && (
                          <div className="mt-2 flex items-center">
                            <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-blue-600 mr-2"></div>
                            <p className="text-sm text-blue-600">주소 변경 중...</p>
                          </div>
                        )}
                      </div>
                      {!updating && (
                        <svg
                          className="w-5 h-5 text-gray-400"
                          fill="none"
                          stroke="currentColor"
                          viewBox="0 0 24 24"
                        >
                          <path
                            strokeLinecap="round"
                            strokeLinejoin="round"
                            strokeWidth={2}
                            d="M9 5l7 7-7 7"
                          />
                        </svg>
                      )}
                    </div>
                  </button>
                ))}
              </div>
            )}

            {/* 결과 없음 */}
            {!loading && stays.length === 0 && !error && (
              <div className="text-center py-12">
                <p className="text-gray-600">매칭되는 Stay를 찾을 수 없습니다.</p>
              </div>
            )}
          </div>

          {/* 푸터 */}
          <div className="flex justify-end p-4 border-t border-gray-200 sticky bottom-0 bg-white">
            <button
              onClick={onClose}
              disabled={loading || updating}
              className="px-4 py-2 bg-gray-100 text-gray-700 rounded-lg hover:bg-gray-200 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
            >
              닫기
            </button>
          </div>
        </div>
      </div>
    </>
  );
};

export default StaySearchModal;
