// 어드민 정산 관리 API 함수
import {
  AdminDashboardResponse,
  AdminSettlementListApiResponse,
  AdminSettlementFilterParams,
  AdminSettlementActionResponse,
  RejectRequestBody,
} from '../types';

// 환경에 따른 API URL 설정
const getApiBaseUrl = () => {
  // 개발 환경
  if (process.env.NODE_ENV === 'development') {
    return process.env.REACT_APP_API_URL || 'http://localhost:8084';
  }
  
  // 운영 환경 - 기본값으로 운영 API 서버 사용
  return process.env.REACT_APP_API_URL || 'https://api.brainbackdoor.com';
};

const API_BASE_URL = getApiBaseUrl();

// 공통 헤더
const getHeaders = () => ({
  'Content-Type': 'application/json',
  'Accept': 'application/json',
  'X-SERVER-AUTH': 'secret',
});

// 공통 에러 처리
const handleResponseError = (response: Response) => {
  if (response.status === 403) {
    throw new Error('접근이 거부되었습니다. API 키를 확인해주세요.');
  } else if (response.status === 404) {
    throw new Error('요청한 리소스를 찾을 수 없습니다.');
  } else if (response.status >= 500) {
    throw new Error('서버에 문제가 발생했습니다. 잠시 후 다시 시도해주세요.');
  } else {
    throw new Error(`HTTP error! status: ${response.status}`);
  }
};

// 네트워크 에러 처리
const handleNetworkError = (error: unknown) => {
  if (error instanceof TypeError && error.message.includes('fetch')) {
    throw new Error('API 서버에 연결할 수 없습니다. 네트워크 연결을 확인하거나 관리자에게 문의하세요.');
  }
  throw error;
};

// 대시보드 통계 조회
export const getAdminSettlementDashboard = async (
  startDate?: string,
  endDate?: string
): Promise<AdminDashboardResponse> => {
  const params = new URLSearchParams();
  if (startDate) params.append('startDate', startDate);
  if (endDate) params.append('endDate', endDate);
  
  const queryString = params.toString();
  const url = `${API_BASE_URL}/api/settlement/admin/dashboard${queryString ? `?${queryString}` : ''}`;
  
  try {
    const response = await fetch(url, {
      method: 'GET',
      headers: getHeaders(),
      mode: 'cors',
    });

    if (!response.ok) {
      handleResponseError(response);
    }

    return response.json();
  } catch (error) {
    handleNetworkError(error);
    throw error;
  }
};

// 정산 요청 목록 조회 (페이지네이션)
export const getAdminSettlementRequests = async (
  params: AdminSettlementFilterParams = {}
): Promise<AdminSettlementListApiResponse> => {
  const searchParams = new URLSearchParams();
  
  if (params.status) searchParams.append('status', params.status);
  if (params.hostName) searchParams.append('hostName', params.hostName);
  if (params.hostContact) searchParams.append('hostContact', params.hostContact);
  if (params.startDate) searchParams.append('startDate', params.startDate);
  if (params.endDate) searchParams.append('endDate', params.endDate);
  if (params.page !== undefined) searchParams.append('page', String(params.page));
  if (params.size !== undefined) searchParams.append('size', String(params.size));
  if (params.sort) searchParams.append('sort', params.sort);
  if (params.direction) searchParams.append('direction', params.direction);
  
  const queryString = searchParams.toString();
  const url = `${API_BASE_URL}/api/settlement/admin/requests/page${queryString ? `?${queryString}` : ''}`;
  
  try {
    const response = await fetch(url, {
      method: 'GET',
      headers: getHeaders(),
      mode: 'cors',
    });

    if (!response.ok) {
      handleResponseError(response);
    }

    return response.json();
  } catch (error) {
    handleNetworkError(error);
    throw error;
  }
};

// 정산 요청 승인
export const approveSettlementRequest = async (
  requestId: string
): Promise<AdminSettlementActionResponse> => {
  const url = `${API_BASE_URL}/api/settlement/admin/requests/${requestId}/approve`;
  
  try {
    const response = await fetch(url, {
      method: 'POST',
      headers: getHeaders(),
      mode: 'cors',
    });

    if (!response.ok) {
      // 400 에러는 별도 처리 (상태 조건 불충족)
      if (response.status === 400) {
        const errorData = await response.json();
        throw new Error(errorData.message || '승인할 수 없는 상태입니다.');
      }
      handleResponseError(response);
    }

    return response.json();
  } catch (error) {
    handleNetworkError(error);
    throw error;
  }
};

// 정산 요청 반려
export const rejectSettlementRequest = async (
  requestId: string,
  body: RejectRequestBody
): Promise<AdminSettlementActionResponse> => {
  const url = `${API_BASE_URL}/api/settlement/admin/requests/${requestId}/reject`;
  
  try {
    const response = await fetch(url, {
      method: 'POST',
      headers: getHeaders(),
      mode: 'cors',
      body: JSON.stringify(body),
    });

    if (!response.ok) {
      // 400 에러는 별도 처리 (상태 조건 불충족 또는 사유 누락)
      if (response.status === 400) {
        const errorData = await response.json();
        throw new Error(errorData.message || '반려할 수 없습니다.');
      }
      handleResponseError(response);
    }

    return response.json();
  } catch (error) {
    handleNetworkError(error);
    throw error;
  }
};

