import React, { useRef, useEffect, useState } from 'react';
import { copyToClipboard } from '../utils/clipboardUtils';
import { useToast } from '../hooks/useToast';

interface PasswordDisplayModalProps {
  isOpen: boolean;
  password: string;
  hostName: string;
  onClose: () => void;
}

const PasswordDisplayModal: React.FC<PasswordDisplayModalProps> = ({
  isOpen,
  password,
  hostName,
  onClose,
}) => {
  const modalRef = useRef<HTMLDivElement>(null);
  const [isCopying, setIsCopying] = useState(false);
  const { showToast } = useToast();

  // ESC 키 감지
  useEffect(() => {
    const handleEscapeKey = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        onClose();
      }
    };

    if (isOpen) {
      document.addEventListener('keydown', handleEscapeKey);
    }

    return () => {
      document.removeEventListener('keydown', handleEscapeKey);
    };
  }, [isOpen, onClose]);

  const handleCopy = async () => {
    setIsCopying(true);
    try {
      const success = await copyToClipboard(password);
      if (success) {
        showToast('비밀번호가 복사되었습니다.', 'success');
      } else {
        showToast('복사에 실패했습니다.', 'error');
      }
    } catch (error) {
      showToast('복사에 실패했습니다.', 'error');
    } finally {
      setIsCopying(false);
    }
  };

  if (!isOpen) {
    return null;
  }

  return (
    <>
      {/* 배경 딤 */}
      <div className="fixed inset-0 bg-black bg-opacity-50 z-[60] flex items-center justify-center p-4">
        {/* 모달 */}
        <div
          ref={modalRef}
          className="bg-white rounded-lg shadow-xl w-full max-w-md animate-fade-in"
        >
          {/* 헤더 */}
          <div className="flex items-center justify-between p-4 border-b border-gray-200">
            <h3 className="text-lg font-medium text-gray-900">비밀번호 초기화 완료</h3>
            <button
              onClick={onClose}
              className="text-gray-400 hover:text-gray-600 transition-colors"
              aria-label="모달 닫기"
            >
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
              </svg>
            </button>
          </div>

          {/* 내용 */}
          <div className="p-6">
            <p className="text-gray-700 mb-4">
              <span className="font-semibold">{hostName}</span> 호스트의 비밀번호가 초기화되었습니다.
            </p>
            <div className="bg-gray-50 rounded-lg p-4 mb-4">
              <label className="block text-sm font-medium text-gray-700 mb-2">
                새 비밀번호
              </label>
              <div className="flex items-center gap-2">
                <code className="flex-1 px-3 py-2 bg-white border border-gray-300 rounded-lg font-mono text-lg text-gray-900">
                  {password}
                </code>
                <button
                  onClick={handleCopy}
                  disabled={isCopying}
                  className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  {isCopying ? '복사 중...' : '복사'}
                </button>
              </div>
            </div>
            <p className="text-sm text-gray-500">
              비밀번호를 복사하여 호스트에게 전달해주세요.
            </p>
          </div>

          {/* 하단 버튼 */}
          <div className="flex justify-end p-4 border-t border-gray-200">
            <button
              onClick={onClose}
              className="px-4 py-2 bg-gray-200 text-gray-700 rounded-lg hover:bg-gray-300 transition-colors"
            >
              닫기
            </button>
          </div>
        </div>
      </div>
    </>
  );
};

export default PasswordDisplayModal;

