import React from 'react';
import { Manual } from '../types';
import { formatDate } from '../utils/dateUtils';
import { getPlainTextPreview } from '../utils/markdownUtils';

interface ManualCardProps {
  manual: Manual;
  isAdmin?: boolean;
  onClick?: () => void;
  onEdit?: (manual: Manual) => void;
  onDelete?: (manual: Manual) => void;
}

const ManualCard: React.FC<ManualCardProps> = ({
  manual,
  isAdmin = false,
  onClick,
  onEdit,
  onDelete,
}) => {
  const handleCardClick = (e: React.MouseEvent) => {
    // 버튼 클릭 시에는 카드 클릭 이벤트 발생하지 않도록
    if ((e.target as HTMLElement).closest('button')) {
      return;
    }
    onClick?.();
  };

  const handleEditClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    onEdit?.(manual);
  };

  const handleDeleteClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    onDelete?.(manual);
  };

  const preview = getPlainTextPreview(manual.content, 150);

  return (
    <div
      onClick={handleCardClick}
      className="bg-white rounded-lg shadow-sm p-6 mb-4 cursor-pointer hover:shadow-md transition-shadow border border-gray-200"
    >
      <div className="flex justify-between items-start mb-3">
        <div className="flex-1">
          <h3 className="text-lg font-semibold text-gray-900 mb-1">
            {manual.title} <span className="text-sm text-gray-500">(v{manual.version})</span>
          </h3>
          <div className="flex items-center gap-3 text-sm text-gray-500 mb-2">
            <span className="px-2 py-1 bg-blue-100 text-blue-700 rounded">
              {manual.categoryName}
            </span>
            <span>{formatDate(manual.createdDate)}</span>
          </div>
        </div>
        {isAdmin && (
          <div className="flex gap-2 ml-4">
            <button
              onClick={handleEditClick}
              className="px-3 py-1 text-sm bg-blue-600 text-white rounded hover:bg-blue-700 transition-colors"
            >
              수정
            </button>
            <button
              onClick={handleDeleteClick}
              className="px-3 py-1 text-sm bg-red-600 text-white rounded hover:bg-red-700 transition-colors"
            >
              삭제
            </button>
          </div>
        )}
      </div>
      {preview && (
        <p className="text-gray-600 text-sm line-clamp-2">{preview}</p>
      )}
    </div>
  );
};

export default ManualCard;
