import { jsPDF } from 'jspdf';

// 포스터 이미지 로드
export const loadPosterImage = (): Promise<HTMLImageElement> => {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.crossOrigin = 'anonymous';
    img.onload = () => resolve(img);
    img.onerror = () => reject(new Error('포스터 이미지를 불러올 수 없습니다.'));
    img.src = `${process.env.PUBLIC_URL}/poster.jpg`;
  });
};

export interface PosterPageData {
  imageData: string;
  width: number;
  height: number;
}

// 포스터 + QR 코드 합성 → 이미지 데이터 반환
export const composePosterPage = (
  posterImg: HTMLImageElement,
  qrCanvas: HTMLCanvasElement,
  stayName: string
): PosterPageData => {
  const offscreen = document.createElement('canvas');
  offscreen.width = posterImg.naturalWidth;
  offscreen.height = posterImg.naturalHeight;
  const ctx = offscreen.getContext('2d');
  if (!ctx) throw new Error('Canvas context를 생성할 수 없습니다.');

  // 흰색 배경 채우기
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(0, 0, offscreen.width, offscreen.height);

  // 포스터 이미지 그리기
  ctx.drawImage(posterImg, 0, 0);

  // 포스터 내 흰색 QR 영역 좌표 (1748x2480 기준)
  const whiteArea = { x: 547, y: 1042, width: 654, height: 642 };

  // QR 코드를 흰색 영역 중앙에 배치 (여백 5px)
  const margin = 5;
  const qrSize = Math.min(whiteArea.width, whiteArea.height) - margin * 2;
  const qrX = whiteArea.x + (whiteArea.width - qrSize) / 2;
  const qrY = whiteArea.y + (whiteArea.height - qrSize) / 2;

  ctx.drawImage(qrCanvas, qrX, qrY, qrSize, qrSize);

  // 우측 하단에 Stay 주소 텍스트 표시 (노란색, 작은 크기)
  const fontSize = 32;
  ctx.font = `bold ${fontSize}px sans-serif`;
  ctx.fillStyle = '#FFD700';
  ctx.textAlign = 'right';
  ctx.textBaseline = 'bottom';
  ctx.fillText(stayName, offscreen.width - 60, offscreen.height - 40);

  return {
    imageData: offscreen.toDataURL('image/jpeg', 0.95),
    width: offscreen.width,
    height: offscreen.height,
  };
};

// PDF 페이지에 흰색 배경을 채우는 헬퍼
const fillPageWhite = (pdf: jsPDF, width: number, height: number): void => {
  pdf.setFillColor(255, 255, 255);
  pdf.rect(0, 0, width, height, 'F');
};

// 단일 포스터 PDF 다운로드
export const downloadSinglePosterPdf = (page: PosterPageData, fileName: string): void => {
  const pdf = new jsPDF({
    orientation: page.height > page.width ? 'portrait' : 'landscape',
    unit: 'px',
    format: [page.width, page.height],
  });
  fillPageWhite(pdf, page.width, page.height);
  pdf.addImage(page.imageData, 'JPEG', 0, 0, page.width, page.height);
  pdf.save(fileName);
};

// 다중 포스터 PDF 다운로드 (페이지 병합)
export const downloadBatchPosterPdf = (pages: PosterPageData[], fileName: string): void => {
  if (pages.length === 0) return;

  const firstPage = pages[0];
  const pdf = new jsPDF({
    orientation: firstPage.height > firstPage.width ? 'portrait' : 'landscape',
    unit: 'px',
    format: [firstPage.width, firstPage.height],
  });
  fillPageWhite(pdf, firstPage.width, firstPage.height);
  pdf.addImage(firstPage.imageData, 'JPEG', 0, 0, firstPage.width, firstPage.height);

  for (let i = 1; i < pages.length; i++) {
    const page = pages[i];
    pdf.addPage([page.width, page.height], page.height > page.width ? 'portrait' : 'landscape');
    fillPageWhite(pdf, page.width, page.height);
    pdf.addImage(page.imageData, 'JPEG', 0, 0, page.width, page.height);
  }

  pdf.save(fileName);
};
