import React, { useState, useCallback, useEffect } from 'react';
import { DeeFranchiseResponse, DeeFranchiseMenuResponse, FranchiseMenuPriceResponse } from '../types';
import { getFranchises, getFranchiseMenus, getMenuPrices, updateMenuPrices } from '../utils/franchiseMenuPriceApi';
import { useToast } from '../hooks/useToast';
import MenuPriceConfirmModal from '../components/MenuPriceConfirmModal';

const MenuPriceManagementPage: React.FC = () => {
  const { showToast } = useToast();

  // 프랜차이즈 목록 상태
  const [franchises, setFranchises] = useState<DeeFranchiseResponse[]>([]);
  const [isFranchisesLoading, setIsFranchisesLoading] = useState(true);

  // 메뉴 목록 상태
  const [menus, setMenus] = useState<DeeFranchiseMenuResponse[]>([]);
  const [isMenusLoading, setIsMenusLoading] = useState(false);

  // 검색 상태
  const [franchiseId, setFranchiseId] = useState('');
  const [selectedMenuName, setSelectedMenuName] = useState('');

  // 결과 상태
  const [prices, setPrices] = useState<FranchiseMenuPriceResponse[]>([]);
  const [hasSearched, setHasSearched] = useState(false);
  const [isSearching, setIsSearching] = useState(false);

  // 가격 변경 상태
  const [newPriceInput, setNewPriceInput] = useState('');
  const [isUpdating, setIsUpdating] = useState(false);

  // 모달 상태
  const [isModalOpen, setIsModalOpen] = useState(false);

  // 검색에 사용된 값 기록 (재조회 시 사용)
  const [searchedFranchiseId, setSearchedFranchiseId] = useState('');
  const [searchedMenuName, setSearchedMenuName] = useState('');

  // 페이지 진입 시 프랜차이즈 목록 로드
  useEffect(() => {
    const loadFranchises = async () => {
      setIsFranchisesLoading(true);
      try {
        const result = await getFranchises('ko');
        result.sort((a, b) => a.name.localeCompare(b.name, 'ko'));
        setFranchises(result);
      } catch (error) {
        const message = error instanceof Error ? error.message : '프랜차이즈 목록을 불러오지 못했습니다.';
        showToast(message, 'error');
      } finally {
        setIsFranchisesLoading(false);
      }
    };
    loadFranchises();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // 프랜차이즈 선택 시 메뉴 목록 로드
  useEffect(() => {
    if (!franchiseId) {
      setMenus([]);
      setSelectedMenuName('');
      return;
    }

    const loadMenus = async () => {
      setIsMenusLoading(true);
      setMenus([]);
      setSelectedMenuName('');
      // 프랜차이즈 변경 시 이전 검색 결과 초기화
      setPrices([]);
      setHasSearched(false);
      setNewPriceInput('');
      try {
        const result = await getFranchiseMenus(franchiseId, 'ko');
        setMenus(result);
      } catch (error) {
        const message = error instanceof Error ? error.message : '메뉴 목록을 불러오지 못했습니다.';
        showToast(message, 'error');
      } finally {
        setIsMenusLoading(false);
      }
    };
    loadMenus();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [franchiseId]);

  // 가격 조회
  const handleSearch = useCallback(async () => {
    if (!franchiseId) {
      showToast('프랜차이즈를 선택해주세요.', 'error');
      return;
    }
    if (!selectedMenuName) {
      showToast('메뉴를 선택해주세요.', 'error');
      return;
    }

    setIsSearching(true);
    setHasSearched(true);
    setNewPriceInput('');

    try {
      const result = await getMenuPrices(franchiseId, selectedMenuName);
      result.sort((a, b) => a.storeName.localeCompare(b.storeName, 'ko'));
      setPrices(result);
      setSearchedFranchiseId(franchiseId);
      setSearchedMenuName(selectedMenuName);

      if (result.length === 0) {
        showToast('검색 결과가 없습니다.', 'info');
      }
    } catch (error) {
      const message = error instanceof Error ? error.message : '가격 조회 중 오류가 발생했습니다.';
      showToast(message, 'error');
      setPrices([]);
    } finally {
      setIsSearching(false);
    }
  }, [franchiseId, selectedMenuName, showToast]);

  // 가격 변경 확인 모달 열기
  const handleOpenConfirmModal = () => {
    const newPrice = parseInt(newPriceInput, 10);
    if (isNaN(newPrice) || newPrice < 0) {
      showToast('올바른 가격을 입력해주세요.', 'error');
      return;
    }
    setIsModalOpen(true);
  };

  // 가격 일괄 변경
  const handleConfirmUpdate = useCallback(async () => {
    const newPrice = parseInt(newPriceInput, 10);
    if (isNaN(newPrice) || newPrice < 0) {
      showToast('올바른 가격을 입력해주세요.', 'error');
      return;
    }

    setIsUpdating(true);
    try {
      const result = await updateMenuPrices(searchedFranchiseId, {
        menuName: searchedMenuName,
        newPrice,
      });

      setIsModalOpen(false);
      showToast(`${result.updatedCount}개 매장의 가격이 ${newPrice.toLocaleString()}원으로 변경되었습니다.`, 'success');

      // updatedCount와 현재 조회 결과 건수가 다르면 경고
      if (result.updatedCount !== prices.length) {
        showToast(
          `변경된 매장 수(${result.updatedCount})가 조회 결과(${prices.length})와 다릅니다. 메뉴명을 확인해주세요.`,
          'info',
          5000
        );
      }

      // 변경 결과 재조회
      const refreshed = await getMenuPrices(searchedFranchiseId, searchedMenuName);
      refreshed.sort((a, b) => a.storeName.localeCompare(b.storeName, 'ko'));
      setPrices(refreshed);
      setNewPriceInput('');
    } catch (error) {
      const message = error instanceof Error ? error.message : '가격 변경 중 오류가 발생했습니다.';
      showToast(message, 'error');
    } finally {
      setIsUpdating(false);
    }
  }, [newPriceInput, searchedFranchiseId, searchedMenuName, prices.length, showToast]);

  // 가격 통계 계산
  const getPriceStats = () => {
    if (prices.length === 0) return null;
    const priceSet = new Set(prices.map((p) => p.price));
    const hasDifferentPrices = priceSet.size > 1;
    const priceCount = new Map<number, number>();
    prices.forEach((p) => {
      priceCount.set(p.price, (priceCount.get(p.price) || 0) + 1);
    });
    let mostCommonPrice = prices[0].price;
    let maxCount = 0;
    priceCount.forEach((count, price) => {
      if (count > maxCount) {
        maxCount = count;
        mostCommonPrice = price;
      }
    });
    return { hasDifferentPrices, mostCommonPrice };
  };

  const priceStats = getPriceStats();
  const parsedNewPrice = parseInt(newPriceInput, 10);
  const isValidNewPrice = !isNaN(parsedNewPrice) && parsedNewPrice >= 0;
  const canUpdate = prices.length > 0 && isValidNewPrice;

  return (
    <div className="h-full overflow-auto">
      <div className="max-w-5xl mx-auto px-4 py-6">
        {/* 페이지 헤더 */}
        <div className="mb-6">
          <h1 className="text-2xl font-bold text-gray-900">메뉴 가격 관리</h1>
          <p className="text-sm text-gray-500 mt-1">
            프랜차이즈 매장의 메뉴 가격을 조회하고 일괄 변경합니다.
          </p>
        </div>

        {/* 검색 영역 */}
        <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-5 mb-6">
          <div className="flex flex-col sm:flex-row gap-3">
            {/* 프랜차이즈 선택 */}
            <div className="flex-1">
              <label className="block text-sm font-medium text-gray-700 mb-1">
                프랜차이즈
              </label>
              <select
                value={franchiseId}
                onChange={(e) => setFranchiseId(e.target.value)}
                disabled={isFranchisesLoading}
                className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500 bg-white disabled:bg-gray-100 disabled:text-gray-400"
              >
                <option value="">
                  {isFranchisesLoading ? '불러오는 중...' : '프랜차이즈 선택'}
                </option>
                {franchises.map((f) => (
                  <option key={f.id} value={f.id}>
                    {f.name}
                  </option>
                ))}
              </select>
            </div>

            {/* 메뉴 선택 */}
            <div className="flex-1">
              <label className="block text-sm font-medium text-gray-700 mb-1">
                메뉴
              </label>
              <select
                value={selectedMenuName}
                onChange={(e) => setSelectedMenuName(e.target.value)}
                disabled={!franchiseId || isMenusLoading}
                className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500 bg-white disabled:bg-gray-100 disabled:text-gray-400"
              >
                <option value="">
                  {!franchiseId
                    ? '프랜차이즈를 먼저 선택하세요'
                    : isMenusLoading
                    ? '메뉴 불러오는 중...'
                    : menus.length === 0
                    ? '등록된 메뉴가 없습니다'
                    : '메뉴 선택'}
                </option>
                {menus.map((m) => (
                  <option key={m.id} value={m.name}>
                    {m.name}
                  </option>
                ))}
              </select>
            </div>

            {/* 검색 버튼 */}
            <div className="flex items-end">
              <button
                onClick={handleSearch}
                disabled={isSearching || !franchiseId || !selectedMenuName}
                className="w-full sm:w-auto px-5 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors text-sm font-medium disabled:opacity-50 flex items-center justify-center"
              >
                {isSearching ? (
                  <>
                    <svg className="animate-spin -ml-1 mr-2 h-4 w-4 text-white" fill="none" viewBox="0 0 24 24">
                      <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" />
                      <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z" />
                    </svg>
                    검색 중...
                  </>
                ) : (
                  <>
                    <svg className="w-4 h-4 mr-1.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                    </svg>
                    검색
                  </>
                )}
              </button>
            </div>
          </div>
        </div>

        {/* 가격 일괄 변경 영역 — 검색 결과 위 */}
        {prices.length > 0 && (
          <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-5 mb-6">
            <h2 className="text-sm font-semibold text-gray-900 mb-4">가격 일괄 변경</h2>
            <div className="flex flex-col sm:flex-row gap-3 items-end">
              <div className="flex-1">
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  새 가격 (원)
                </label>
                <div className="relative">
                  <input
                    type="number"
                    value={newPriceInput}
                    onChange={(e) => setNewPriceInput(e.target.value)}
                    onKeyDown={(e) => {
                      if (e.key === 'Enter' && canUpdate) {
                        handleOpenConfirmModal();
                      }
                    }}
                    placeholder="변경할 가격 입력"
                    min="0"
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500 pr-10"
                  />
                  <span className="absolute right-3 top-1/2 transform -translate-y-1/2 text-sm text-gray-400">
                    원
                  </span>
                </div>
              </div>
              <button
                onClick={handleOpenConfirmModal}
                disabled={!canUpdate}
                className="w-full sm:w-auto px-5 py-2 bg-orange-600 text-white rounded-lg hover:bg-orange-700 transition-colors text-sm font-medium disabled:opacity-40 disabled:cursor-not-allowed"
              >
                일괄 변경
              </button>
            </div>

            {/* 변경 미리보기 */}
            {isValidNewPrice && prices.length > 0 && (
              <div className="mt-4 p-3 bg-blue-50 border border-blue-200 rounded-lg">
                <p className="text-sm text-blue-700">
                  <span className="font-medium">{prices.length}개 매장</span>의{' '}
                  <span className="font-medium">{searchedMenuName}</span> 가격이{' '}
                  <span className="font-medium">{parsedNewPrice.toLocaleString()}원</span>으로 변경됩니다.
                </p>
              </div>
            )}
          </div>
        )}

        {/* 검색 결과 테이블 */}
        {hasSearched && (
          <div className="bg-white rounded-lg shadow-sm border border-gray-200 mb-6">
            {/* 결과 헤더 */}
            <div className="px-5 py-3 border-b border-gray-200 flex items-center justify-between">
              <div className="flex items-center gap-2">
                <h2 className="text-sm font-semibold text-gray-900">검색 결과</h2>
                <span className="text-xs text-gray-500 bg-gray-100 px-2 py-0.5 rounded-full">
                  {prices.length}개 매장
                </span>
              </div>
              {priceStats?.hasDifferentPrices && (
                <span className="text-xs text-amber-600 bg-amber-50 px-2 py-0.5 rounded-full flex items-center">
                  <svg className="w-3.5 h-3.5 mr-1" fill="currentColor" viewBox="0 0 20 20">
                    <path fillRule="evenodd" d="M8.257 3.099c.765-1.36 2.722-1.36 3.486 0l5.58 9.92c.75 1.334-.213 2.98-1.742 2.98H4.42c-1.53 0-2.493-1.646-1.743-2.98l5.58-9.92zM11 13a1 1 0 11-2 0 1 1 0 012 0zm-1-8a1 1 0 00-1 1v3a1 1 0 002 0V6a1 1 0 00-1-1z" clipRule="evenodd" />
                  </svg>
                  매장별 가격 상이
                </span>
              )}
            </div>

            {/* 테이블 */}
            {prices.length > 0 ? (
              <div className="overflow-x-auto">
                <table className="w-full text-sm">
                  <thead>
                    <tr className="bg-gray-50 border-b border-gray-200">
                      <th className="text-left px-5 py-3 text-xs font-medium text-gray-500 uppercase tracking-wider">매장명</th>
                      <th className="text-left px-5 py-3 text-xs font-medium text-gray-500 uppercase tracking-wider">메뉴명</th>
                      <th className="text-right px-5 py-3 text-xs font-medium text-gray-500 uppercase tracking-wider">현재 가격</th>
                      {isValidNewPrice && (
                        <th className="text-right px-5 py-3 text-xs font-medium text-gray-500 uppercase tracking-wider">변경 후 가격</th>
                      )}
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-100">
                    {prices.map((item) => {
                      const isDifferent = priceStats?.hasDifferentPrices && item.price !== priceStats.mostCommonPrice;
                      const priceChanged = isValidNewPrice && item.price !== parsedNewPrice;
                      return (
                        <tr
                          key={item.menuItemId}
                          className={`hover:bg-gray-50 transition-colors ${isDifferent ? 'bg-amber-50' : ''}`}
                        >
                          <td className="px-5 py-3 text-gray-900">{item.storeName}</td>
                          <td className="px-5 py-3 text-gray-700">{item.menuName}</td>
                          <td className={`px-5 py-3 text-right font-medium ${isDifferent ? 'text-amber-700' : 'text-gray-900'}`}>
                            {item.price.toLocaleString()}원
                          </td>
                          {isValidNewPrice && (
                            <td className="px-5 py-3 text-right font-medium">
                              {priceChanged ? (
                                <span className="text-blue-600">{parsedNewPrice.toLocaleString()}원</span>
                              ) : (
                                <span className="text-gray-400">변경 없음</span>
                              )}
                            </td>
                          )}
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            ) : (
              <div className="px-5 py-12 text-center">
                <svg className="w-12 h-12 text-gray-300 mx-auto mb-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M9.172 16.172a4 4 0 015.656 0M9 10h.01M15 10h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                </svg>
                <p className="text-sm text-gray-500">검색 결과가 없습니다.</p>
                <p className="text-xs text-gray-400 mt-1">프랜차이즈 또는 메뉴를 확인해주세요.</p>
              </div>
            )}
          </div>
        )}

        {/* 확인 모달 */}
        <MenuPriceConfirmModal
          isOpen={isModalOpen}
          menuName={searchedMenuName}
          newPrice={parsedNewPrice || 0}
          storeCount={prices.length}
          isLoading={isUpdating}
          onConfirm={handleConfirmUpdate}
          onClose={() => setIsModalOpen(false)}
        />
      </div>
    </div>
  );
};

export default MenuPriceManagementPage;
